query SmartSearchWithParams($query: String!, $context: SearchContext, $options: SmartSearchOptions) {
  smartSearch(query: $query, context: $context, options: $options) {
    results {
      nodes {
        id
        title
        content
        relevanceScore
        matchedFields
        highlights
        relationships {
          id
          title
          relationshipType
          strength
        }
      }
      tables {
        id
        identifier
        description
        relevanceScore
        matchReason
      }
      templates {
        id
        identifier
        name
        relevanceScore
        suggestedVariables
      }
    }
    suggestions {
      queryCorrections
      semanticExpansions
      relatedTerms
      filters
    }
    analytics {
      searchTime
      indexesUsed
      cacheHit
      resultsCount
    }
    recommendations {
      type
      items
      confidence
      reasoning
    }
  }
}
